17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.ArrayList;
21	import java.util.Collection;
22	import java.util.List;
23	
24	import org.springframework.http.HttpHeaders;
25	import org.springframework.http.HttpStatus;
26	import org.springframework.http.ResponseEntity;
27	import org.springframework.samples.petclinic.mapper.OwnerMapper;
28	import org.springframework.samples.petclinic.mapper.PetMapper;
29	import org.springframework.samples.petclinic.mapper.VisitMapper;
30	import org.springframework.samples.petclinic.model.Owner;
31	import org.springframework.samples.petclinic.model.Pet;
32	import org.springframework.samples.petclinic.model.Visit;
33	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerException;
34	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
35	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
36	import org.springframework.samples.petclinic.rest.api.OwnersApi;
37	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
38	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.PetDto;
40	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.VisitDto;
42	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
43	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
44	import org.springframework.samples.petclinic.service.ClinicService;
45	import org.springframework.security.access.prepost.PreAuthorize;
46	import org.springframework.web.bind.annotation.CrossOrigin;
47	import org.springframework.web.bind.annotation.RequestMapping;
48	import org.springframework.web.bind.annotation.RestController;
49	import org.springframework.web.util.UriComponentsBuilder;
50	
51	import jakarta.transaction.Transactional;
52	
53	/**
54	 * @author Vitaliy Fedoriv
55	 */
56	
57	@RestController
58	@CrossOrigin(exposedHeaders = "errors, content-type")
59	@RequestMapping("/api")
60	public class OwnerRestControllerV1 implements OwnersApi {
61	
62	    private final ClinicService clinicService;
63	
64	    private final OwnerMapper ownerMapper;
65	
66	    private final PetMapper petMapper;
67	
68	    private final VisitMapper visitMapper;
69	
70	    private final TelephoneNormalizer telephoneNormalizer;
71	
72	    public OwnerRestControllerV1(ClinicService clinicService,
73	                                 OwnerMapper ownerMapper,
74	                                 PetMapper petMapper,
75	                                 VisitMapper visitMapper,
76	                                 TelephoneNormalizer telephoneNormalizer) {
77	        this.clinicService = clinicService;
78	        this.ownerMapper = ownerMapper;
79	        this.petMapper = petMapper;
80	        this.visitMapper = visitMapper;
81	        this.telephoneNormalizer = telephoneNormalizer;
82	    }
83	
84	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
85	    @Override
86	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
87	        Collection<Owner> owners;
88	        if (lastName != null) {
89	            owners = this.clinicService.findOwnerByLastName(lastName);
90	        } else {
91	            owners = this.clinicService.findAllOwners();
92	        }
93	        if (owners.isEmpty()) {
94	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
95	        }
96	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
97	    }
98	
99	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
100	    @Override
101	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
102	        Owner owner = this.clinicService.findOwnerById(ownerId);
103	        if (owner == null) {
104	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
105	        }
106	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
107	    }
108	
109	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
110	    @Override
111	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
112	        normalizeAndValidate(ownerFieldsDto);
113	        HttpHeaders headers = new HttpHeaders();
114	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
115	        owner.setCustomerCode(generateCustomerCode(owner.getLastName()));
116	        this.clinicService.saveOwner(owner);
117	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
118	        headers.setLocation(UriComponentsBuilder.newInstance()
119	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
120	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
121	    }
122	
123	    /**
124	     * Prepares a new owner's payload for persistence, applying every rule an incoming owner must satisfy before it is
125	     * saved. Required fields are checked first; the telephone is then normalized to its canonical stored form, written
126	     * back onto the payload and rejected if another owner already uses it; the email is canonicalized; and a missing
127	     * registration date defaults to the current date. The payload is mutated in place so the caller can map and save it
128	     * directly.
129	     *
130	     * @param ownerFieldsDto the incoming owner payload, mutated in place
131	     * @throws MissingOwnerFieldsException if any required field is missing or blank
132	     * @throws DuplicateTelephoneException if another owner already uses the normalized telephone
133	     */
134	    private void normalizeAndValidate(OwnerFieldsDto ownerFieldsDto) {
135	        validateRequiredFields(ownerFieldsDto);
136	        String telephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
137	        ownerFieldsDto.setTelephone(telephone);
138	        requireUniqueTelephone(telephone);
139	        requireUniqueHousehold(ownerFieldsDto);
140	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
141	        if (ownerFieldsDto.getRegistrationDate() == null) {
142	            ownerFieldsDto.setRegistrationDate(LocalDate.now());
143	        }
144	    }
145	
146	    /**
147	     * Builds an owner's {@code customerCode}, formatted {@code <LAST3>-<NNNN>}. {@code LAST3} is the upper-cased first
148	     * three letters of the last name and {@code NNNN} is a global 4-digit zero-padded sequence equal to one more than
149	     * the current number of owners (e.g. {@code SMI-0007}).
150	     *
151	     * @param lastName the owner's last name
152	     * @return the generated customer code
153	     */
154	    private String generateCustomerCode(String lastName) {
155	        String prefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
156	        int sequence = this.clinicService.findAllOwners().size() + 1;
157	        return String.format("%s-%04d", prefix, sequence);
158	    }
159	
160	    /**
161	     * Rejects an owner payload that omits or leaves blank any required field. Bean Validation already rejects missing
162	     * ({@code null}) required fields, but permits values that are blank (empty or whitespace-only) for fields without a
163	     * stricter pattern, so this check enforces the "missing or blank" rule uniformly across every required field.
164	     *
165	     * @param ownerFieldsDto the owner payload to validate
166	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or telephone is missing or blank
167	     */
168	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
169	        List<String> missingFields = new ArrayList<>();
170	        requireText(missingFields, "firstName", ownerFieldsDto.getFirstName());
171	        requireText(missingFields, "lastName", ownerFieldsDto.getLastName());
172	        requireText(missingFields, "address", ownerFieldsDto.getAddress());
173	        requireText(missingFields, "city", ownerFieldsDto.getCity());
174	        requireText(missingFields, "telephone", ownerFieldsDto.getTelephone());
175	        if (!missingFields.isEmpty()) {
176	            throw new MissingOwnerFieldsException(missingFields);
177	        }
178	    }
179	
180	    private void requireText(List<String> missingFields, String fieldName, String value) {
181	        if (value == null || value.isBlank()) {
182	            missingFields.add(fieldName);
183	        }
184	    }
185	
186	    /**
187	     * Normalizes an optional owner email. A syntactically valid address is already enforced by Bean Validation on the
188	     * request payload, so this only canonicalizes the value that gets stored and returned by lower-casing it. A missing
189	     * (blank or {@code null}) email is left untouched, since the field is optional.
190	     *
191	     * @param email the raw email value from the request, may be {@code null}
192	     * @return the lower-cased email, or the original value when none was supplied
193	     */
194	    private String normalizeEmail(String email) {
195	        if (email == null || email.isBlank()) {
196	            return email;
197	        }
198	        return email.toLowerCase();
199	    }
200	
201	    /**
202	     * Rejects creating an owner whose normalized telephone is already used by another owner. Existing owners' stored
203	     * telephones are canonicalized the same way before comparison, so the rule holds regardless of how their number was
204	     * originally formatted.
205	     *
206	     * @param telephone the normalized telephone of the owner being created
207	     * @throws DuplicateTelephoneException if any existing owner already uses the same normalized telephone
208	     */
209	    private void requireUniqueTelephone(String telephone) {
210	        boolean inUse = this.clinicService.findAllOwners().stream()
211	            .map(existing -> telephoneNormalizer.canonicalize(existing.getTelephone()))
212	            .anyMatch(telephone::equals);
213	        if (inUse) {
214	            throw new DuplicateTelephoneException("telephone is already in use by another owner");
215	        }
216	    }
217	
218	    /**
219	     * Rejects creating an owner who shares both a last name and an address with an existing owner, unless the request
220	     * opts in by setting {@code sharesHousehold} to {@code true}. Both fields are compared case-insensitively after
221	     * collapsing runs of whitespace to a single space and trimming, so incidental formatting differences do not defeat
222	     * the rule.
223	     *
224	     * @param ownerFieldsDto the incoming owner payload
225	     * @throws DuplicateOwnerException if another owner already has the same last name and address and the request does
226	     *                                 not set {@code sharesHousehold}
227	     */
228	    private void requireUniqueHousehold(OwnerFieldsDto ownerFieldsDto) {
229	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
230	            return;
231	        }
232	        String lastName = collapseWhitespace(ownerFieldsDto.getLastName());
233	        String address = collapseWhitespace(ownerFieldsDto.getAddress());
234	        boolean duplicate = this.clinicService.findAllOwners().stream()
235	            .anyMatch(existing -> collapseWhitespace(existing.getLastName()).equalsIgnoreCase(lastName)
236	                && collapseWhitespace(existing.getAddress()).equalsIgnoreCase(address));
237	        if (duplicate) {
238	            throw new DuplicateOwnerException(
239	                "an owner with the same last name and address already exists in this household");
240	        }
241	    }
242	
243	    /**
244	     * Canonicalizes a value for household comparison by trimming it and collapsing every run of whitespace to a single
245	     * space. Case is deliberately preserved here; callers compare the result case-insensitively.
246	     *
247	     * @param value the raw field value, may be {@code null}
248	     * @return the whitespace-collapsed value, or an empty string when {@code null}
249	     */
250	    private String collapseWhitespace(String value) {
251	        if (value == null) {
252	            return "";
253	        }
254	        return value.strip().replaceAll("\\s+", " ");
255	    }
256	
257	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
258	    @Override
259	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
260	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
261	        if (currentOwner == null) {
262	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
263	        }
264	        currentOwner.setAddress(ownerFieldsDto.getAddress());
265	        currentOwner.setCity(ownerFieldsDto.getCity());
266	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
267	        currentOwner.setLastName(ownerFieldsDto.getLastName());
268	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
269	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
270	        this.clinicService.saveOwner(currentOwner);
271	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
272	    }
273	
274	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
275	    @Transactional
276	    @Override
277	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
278	        Owner owner = this.clinicService.findOwnerById(ownerId);
279	        if (owner == null) {
280	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
281	        }
282	        this.clinicService.deleteOwner(owner);
283	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
284	    }
285	
286	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
287	    @Override
288	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
289	        Owner owner = this.clinicService.findOwnerById(ownerId);
290	        if (owner == null) {
291	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
292	        }
293	        HttpHeaders headers = new HttpHeaders();
294	        Pet pet = petMapper.toPet(petFieldsDto);
295	        owner.setId(ownerId);
296	        pet.setOwner(owner);
297	        pet.getType().setName(null);
298	        this.clinicService.savePet(pet);
299	        PetDto petDto = petMapper.toPetDto(pet);
300	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
301	            .buildAndExpand(pet.getId()).toUri());
302	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
303	    }
304	
305	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
306	    @Override
307	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
308	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
309	        if (currentOwner != null) {
310	            Pet currentPet = this.clinicService.findPetById(petId);
311	            if (currentPet != null) {
312	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
313	                currentPet.setName(petFieldsDto.getName());
314	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
315	                this.clinicService.savePet(currentPet);
316	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
317	            }
318	        }
319	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
320	    }
321	
322	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
323	    @Override
324	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
325	        HttpHeaders headers = new HttpHeaders();
326	        Visit visit = visitMapper.toVisit(visitFieldsDto);
327	        Pet pet = new Pet();
328	        pet.setId(petId);
329	        visit.setPet(pet);
330	        this.clinicService.saveVisit(visit);
331	        VisitDto visitDto = visitMapper.toVisitDto(visit);
332	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
333	            .buildAndExpand(visit.getId()).toUri());
334	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
335	    }
336	
337	
338	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
339	    @Override
340	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
341	        Owner owner = this.clinicService.findOwnerById(ownerId);
342	        if (owner != null) {
343	            Pet pet = owner.getPet(petId);
344	            if (pet != null) {
345	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
346	            }
347	        }
348	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
349	    }
350	}
